#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <errno.h>

// Assuming RSFilter and rs_filter_dot_representation are defined elsewhere
// and that the necessary headers are already included in the file.

void rs_filter_visualize(RSFilter *filter) {
    if (!filter) {
        return;
    }

    char *dot_content = rs_filter_dot_representation(filter);
    if (!dot_content) {
        return;
    }

    char *dot_path = NULL;
    char *png_path = NULL;

    int result;

    // Generate a temporary file path for DOT content
    char template[] = "/tmp/filter_graph_XXXXXX";
    dot_path = strdup(template);
    if (!dot_path) {
        free(dot_content);
        return;
    }

    int fd = mkstemp(dot_path);
    if (fd == -1) {
        free(dot_content);
        free(dot_path);
        return;
    }

    // Write the DOT content to the file
    result = write(fd, dot_content, strlen(dot_content));
    if (result == -1) {
        close(fd);
        free(dot_content);
        free(dot_path);
        return;
    }

    close(fd);
    free(dot_content);

    // Generate a temporary file path for the PNG image
    char png_template[] = "/tmp/filter_graph_XXXXXX.png";
    png_path = strdup(png_template);
    if (!png_path) {
        free(dot_path);
        return;
    }

    // Convert the DOT file to a PNG using the dot command
    char command[512];
    snprintf(command, sizeof(command), "dot -Tpng %s > %s", dot_path, png_path);
    int exit_status = system(command);
    if (exit_status == -1 || WIFSIGNALED(exit_status) || WEXITSTATUS(exit_status) != 0) {
        fprintf(stderr, "Warning: Failed to convert DOT file to PNG.\n");
    }

    // Attempt to open the generated PNG file
    snprintf(command, sizeof(command), "gnome-open %s", png_path);
    exit_status = system(command);
    if (exit_status == -1 || WIFSIGNALED(exit_status) || WEXITSTATUS(exit_status) != 0) {
        fprintf(stderr, "Warning: Failed to open the PNG file.\n");
    }

    // Clean up resources
    if (dot_path) {
        unlink(dot_path);
        free(dot_path);
    }

    if (png_path) {
        free(png_path);
    }
}

